-- Sources/further-reading moves from a committed, slug-keyed static file
-- (src/data/blog-sources.ts) into the DB, so it's editable from the
-- console like every other post field instead of requiring a code change
-- and a deploy. Backfills the existing static entries so no post loses
-- its citations; src/data/blog-sources.ts is deleted in this same change.
ALTER TABLE blog_posts ADD COLUMN IF NOT EXISTS sources jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE blog_posts ADD COLUMN IF NOT EXISTS sources_reviewed_at date;

